{"path":"src/store.js","content":"import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// Keeps books in a JSON file. Writes go to a temp file that is then renamed
// over the real one, so a crash mid-write never leaves a half-written file.
export function createStore(filePath) {
  let books = null;
  let queue = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      const data = JSON.parse(await readFile(filePath, "utf8"));
      books = Array.isArray(data.books) ? data.books : [];
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      books = [];
    }
    return books;
  }

  function save() {
    // Serialize writes so concurrent requests can't interleave.
    const snapshot = JSON.stringify({ books }, null, 2);
    queue = queue.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, filePath);
    });
    return queue;
  }

  return {
    async list() {
      return [...(await load())];
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = "" }) {
      const list = await load();
      const book = {
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      list.push(book);
      await save();
      return book;
    },

    async update(id, changes) {
      const book = await this.get(id);
      if (!book) return null;
      if (changes.notes !== undefined) book.notes = changes.notes;
      if (changes.status === "finished" && book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
      } else if (changes.status === "reading") {
        book.status = "reading";
        book.finishedAt = null;
      }
      await save();
      return book;
    },
  };
}
"}

