function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #2455a4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding-left: 1.2rem; }
  li { margin: .4rem 0; }
  form.inline { display: inline; margin-left: .5rem; }
  label { display: block; margin-top: .6rem; }
  input[type=text], textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  textarea { min-height: 6rem; }
  button { margin-top: .6rem; padding: .3rem .8rem; font: inherit; cursor: pointer; }
  form.inline button { margin-top: 0; font-size: .85rem; }
  .muted { color: #777; }
  .error { color: #b00020; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: .8rem; border-radius: 4px; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const link = `<a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a> <span class="muted">by ${escapeHtml(book.author)}</span>`;
  if (book.status === "finished") return `<li>${link}</li>`;
  return `<li>${link}
    <form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
      <button type="submit">Mark finished</button>
    </form></li>`;
}

function section(heading, books, empty) {
  const items = books.length ? `<ul>${books.map(bookItem).join("")}</ul>` : `<p class="muted">${empty}</p>`;
  return `<h2>${heading}</h2>${items}`;
}

function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));
  return layout(
    "My books",
    `<h1>My books</h1>
${section("Currently reading", reading, "Nothing on the go right now.")}
${section("Finished", finished, "No finished books yet.")}
<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
<form method="post" action="/books">
  <label>Title <input type="text" name="title" required maxlength="300" value="${escapeHtml(values.title)}"></label>
  <label>Author <input type="text" name="author" required maxlength="300" value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes" maxlength="20000">${escapeHtml(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

function bookPage(book) {
  const id = encodeURIComponent(book.id);
  const status =
    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${escapeHtml(book.finishedAt.slice(0, 10))}` : ""}`
      : "Currently reading";
  const action =
    book.status === "finished"
      ? `<form method="post" action="/books/${id}/reading"><button type="submit">Move back to reading</button></form>`
      : `<form method="post" action="/books/${id}/finish"><button type="submit">Mark finished</button></form>`;
  return layout(
    book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${escapeHtml(book.title)}</h1>
<p>by ${escapeHtml(book.author)}</p>
<p class="muted">${status}</p>
${action}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : `<p class="muted">No notes yet.</p>`}
<form method="post" action="/books/${id}/notes">
  <label>Edit notes <textarea name="notes" maxlength="20000">${escapeHtml(book.notes)}</textarea></label>
  <button type="submit">Save notes</button>
</form>`,
  );
}

function notFoundPage() {
  return layout("Not found", `<h1>Book not found</h1><p><a href="/">Back to all books</a></p>`);
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.setEncoding("utf8");
    req.on("data", (chunk) => {
      body += chunk;
      if (body.length > MAX_BODY) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
      }
    });
    req.on("end", () => resolve(new URLSearchParams(body)));
    req.on("error", reject);
  });
}

export function createApp(store) {
  return async function handle(req, res) {
    try {
      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([A-Za-z0-9_-]+)(?:\/(finish|reading|notes))?\/?$/);

      if (req.method === "GET" && pathname === "/") {
        return send(res, 200, homePage(await store.list()));
      }

      if (req.method === "POST" && pathname === "/books") {
        const form = await readForm(req);
        const values = {
          title: (form.get("title") ?? "").trim(),
          author: (form.get("author") ?? "").trim(),
          notes: (form.get("notes") ?? "").trim(),
        };
        if (!values.title || !values.author) {
          return send(res, 400, homePage(await store.list(), { error: "Title and author are required.", values }));
        }
        const book = await store.add(values);
        return redirect(res, `/books/${encodeURIComponent(book.id)}`);
      }

      if (bookMatch) {
        const [, id, action] = bookMatch;
        const book = await store.get(id);
        if (!book) return send(res, 404, notFoundPage());

        if (req.method === "GET" && !action) return send(res, 200, bookPage(book));

        if (req.method === "POST" && action) {
          const form = await readForm(req);
          if (action === "finish") await store.update(id, { status: "finished" });
          if (action === "reading") await store.update(id, { status: "reading" });
          if (action === "notes") await store.update(id, { notes: (form.get("notes") ?? "").trim() });
          // Finishing from the list returns you to the list; otherwise stay on the book.
          const back = action === "finish" && (req.headers.referer ?? "").match(/\/$/) ? "/" : `/books/${encodeURIComponent(id)}`;
          return redirect(res, back);
        }
      }

      return send(res, 404, layout("Not found", `<h1>Page not found</h1><p><a href="/">Back to all books</a></p>`));
    } catch (err) {
      console.error(err);
      if (!res.headersSent) send(res, err.status ?? 500, layout("Error", `<h1>Something went wrong</h1>`));
    }
  };
}
"}

