import { createServer } from "node:http";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "../src/store.js";
import { createApp } from "../src/app.js";

let dir, file, server, base;

async function start() {
  server = createServer(createApp(createStore(file)));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields) =>
  fetch(base + path, { method: "POST", body: new URLSearchParams(fields), redirect: "manual" });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("adds a book and shows it under currently reading", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice." });
    expect(res.status).toBe(303);
    const bookUrl = res.headers.get("location");
    expect(bookUrl).toMatch(/^\/books\/[\w-]+$/);

    const home = await (await fetch(base + "/")).text();
    const reading = home.split("<h2>Finished</h2>")[0];
    expect(reading).toContain("Dune");

    const page = await (await fetch(base + bookUrl)).text();
    expect(page).toContain("Dune");
    expect(page).toContain("Frank Herbert");
    expect(page).toContain("Spice.");
  });

  it("marks a book finished", async () => {
    const url = (await post("/books", { title: "Emma", author: "Jane Austen" })).headers.get("location");
    const res = await post(url + "/finish", { from: "list" });
    expect(res.headers.get("location")).toBe("/");

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).not.toContain("Emma");
    expect(finished).toContain("Emma");
  });

  it("persists books across restarts", async () => {
    const url = (await post("/books", { title: "Kindred", author: "Octavia Butler" })).headers.get("location");
    await stop();
    await start();
    const res = await fetch(base + url);
    expect(res.status).toBe(200);
    expect(await res.text()).toContain("Kindred");
    const saved = JSON.parse(await readFile(file, "utf8"));
    expect(saved.books).toHaveLength(1);
  });

  it("escapes HTML in user input", async () => {
    const url = (await post("/books", { title: "<script>x</script>", author: "A" })).headers.get("location");
    const page = await (await fetch(base + url)).text();
    expect(page).not.toContain("<script>x");
    expect(page).toContain("&lt;script&gt;");
  });

  it("rejects missing fields and 404s unknown books", async () => {
    expect((await post("/books", { title: "", author: "x" })).status).toBe(400);
    expect((await fetch(base + "/books/nope")).status).toBe(404);
  });
});
"}

